#include "stdlib/stats/base/dists/burr-type3/median.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/expm1.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/constants/float64/ln_two.h"

/**
* Returns the median of a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* @param c    first shape parameter
* @param d    second shape parameter
* @return     median
*
* @example
* double v = stdlib_base_dists_burr_type3_median( 2.0, 1.0 );
* // returns 1.0
*/
double stdlib_base_dists_burr_type3_median( const double c, const double d ) {
	if (
		stdlib_base_is_nan( c ) ||
		stdlib_base_is_nan( d ) ||
		c <= 0.0 ||
		d <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	return stdlib_base_pow( stdlib_base_expm1( STDLIB_CONSTANT_FLOAT64_LN2 / d ), -1.0 / c );
}
